<script setup lang="ts">
import AppIcon from '../../../../../shared/components/layout/AppIcon.vue'
import type { ExpenseCategory, ExpenseMethod, ProjectExpense } from '../../types/expense'
defineProps<{ expenses: ProjectExpense[]; loading: boolean }>()
const emit = defineEmits<{ void: [expense: ProjectExpense] }>()
const money = new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 })
const date = new Intl.DateTimeFormat('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
const categoryLabels: Record<ExpenseCategory, string> = { transport: 'Transportasi', accommodation: 'Akomodasi', meals: 'Konsumsi', equipment: 'Peralatan', software: 'Software', communication: 'Komunikasi', other: 'Lainnya' }
const methodLabels: Record<ExpenseMethod, string> = { cash: 'Tunai', bank_transfer: 'Transfer bank', other: 'Lainnya' }
</script>
<template>
  <div>
    <div v-if="loading" class="list-state">Memuat pengeluaran...</div>
    <div v-else-if="!expenses.length" class="list-state empty"><span><AppIcon name="receipt" :size="22" /></span><strong>Belum ada pengeluaran</strong><small>Catatan biaya project dan operasional tim akan tampil di sini.</small></div>
    <template v-else>
      <div class="table-wrap"><table><thead><tr><th>Kode</th><th>Project / kategori</th><th>Penerima</th><th>Nominal</th><th>Tanggal / metode</th><th>Status</th><th><span class="sr-only">Aksi</span></th></tr></thead><tbody>
        <tr v-for="expense in expenses" :key="expense.id"><td><span class="code">{{ expense.code }}</span><small v-if="expense.reference" class="subline">Ref. {{ expense.reference }}</small></td><td><span class="stack"><strong>{{ expense.project?.name || 'Operasional tim' }}</strong><small>{{ expense.project?.code || 'Tanpa project' }} · {{ categoryLabels[expense.category] }}</small></span></td><td>{{ expense.paid_to }}</td><td class="amount">{{ money.format(Number(expense.amount)) }}</td><td><span class="stack"><strong>{{ date.format(new Date(`${expense.spent_at}T00:00:00`)) }}</strong><small>{{ methodLabels[expense.method] }}</small></span></td><td><span class="status" :class="expense.status"><i></i>{{ expense.status === 'paid' ? 'Sah' : 'Dikoreksi' }}</span></td><td><button v-if="expense.status === 'paid'" class="void-button" type="button" :aria-label="`Koreksi ${expense.code}`" title="Koreksi pengeluaran" @click="emit('void', expense)"><AppIcon name="rotate-ccw" :size="15" /></button><small v-else class="void-reason">{{ expense.void_reason }}</small></td></tr>
      </tbody></table></div>
      <div class="cards"><article v-for="expense in expenses" :key="expense.id" class="expense-card"><div class="card-top"><div class="identity"><strong>{{ expense.code }}</strong><small>{{ date.format(new Date(`${expense.spent_at}T00:00:00`)) }} · {{ methodLabels[expense.method] }}</small></div><span class="status" :class="expense.status"><i></i>{{ expense.status === 'paid' ? 'Sah' : 'Dikoreksi' }}</span></div><div class="project"><strong>{{ expense.project?.name || 'Operasional tim' }}</strong><small>{{ expense.project?.code || 'Tanpa project' }} · {{ categoryLabels[expense.category] }}</small></div><div class="detail"><span>{{ expense.paid_to }}<small v-if="expense.reference">Ref. {{ expense.reference }}</small></span><strong>{{ money.format(Number(expense.amount)) }}</strong></div><div v-if="expense.status === 'voided'" class="void-note">Alasan koreksi: {{ expense.void_reason }}</div><div v-else class="actions"><button type="button" @click="emit('void', expense)"><AppIcon name="rotate-ccw" :size="14" /> Koreksi pengeluaran</button></div></article></div>
    </template>
  </div>
</template>
